Method.Source:
/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "copyFrom">NDXUmsSignature</param>
/// <param name = "copyTo">NDXUmsSignature</param>
/// <param name = "lCopyToAdminOld">boolean</param>
/// <param name = "only4Alliance">CustAccount</param>
/// <param name = "lAsk">boolean</param>
/// <param name = "lDelete">boolean</param>
/// <param name = "lSic">boolean</param>
/// <returns>boolean</returns>
static server boolean copyFromToByUmsSignature(NDXUmsSignature    copyFrom,
                                    NDXUmsSignature    copyTo,
                                    boolean             lCopyToAdminOld = false,
                                    CustAccount         only4Alliance = '',
                                    boolean             lAsk = true,
                                    boolean             lDelete = true,
                                    boolean             lSic = false)

{
    #define.admin('admin')
    #define.adminAlliance('admin.2')
    #define.adminSalesGroup('admin.3')

    NDXUmsSignature            l_copyToOld;
    NDXUmsSignature            l_copyFromSic;
    SkipAOSValidationPermission skipAOS;

    ;

    //NDX_INTDebug::bpstatic();

    skipAOS = new SkipAOSValidationPermission();
    skipAOS.assert();

    if (!lAsk || box::yesNo(strfmt("@NDX:NDXCopySalesVolumeToSignature", copyFrom, copyTo), DialogButton::No)==DialogButton::Yes)
    {
        l_copyToOld     = strfmt('%1.old', copyTo);
        l_copyFromSic   = strfmt('%1.sic', copyFrom);

        ttsbegin;

        //NDX_TmpCustomerAlliance
        if (lCopyToAdminOld)
        {
            if(lDelete)
            {
                NDXTmpCustomerAlliance::deleteRecords(l_copyToOld, only4Alliance);
            }                
            NDXTmpCustomerAlliance::updateRecords(copyTo, l_copyToOld, false, l_copyFromSic, only4Alliance);
        }
        else
        {
            if(lDelete)
            {
                NDXTmpCustomerAlliance::deleteRecords(copyTo, only4Alliance);
            }
        }
        NDXTmpCustomerAlliance::updateRecords(copyFrom, copyTo, lSic, l_copyFromSic, only4Alliance);

        //NDX_TmpCSAlliance
        if (lCopyToAdminOld)
        {
            if(lDelete)
            {
                NDXTmpCSAlliance::deleteRecords(l_copyToOld, only4Alliance);
            }
            NDXTmpCSAlliance::updateRecords(copyTo, l_copyToOld, false, l_copyFromSic, only4Alliance);
        }
        else
        {
            if(lDelete)
            {
                NDXTmpCSAlliance::deleteRecords(copyTo, only4Alliance);
            }                
        }
        NDXTmpCSAlliance::updateRecords(copyFrom, copyTo, lSic, l_copyFromSic, only4Alliance);

        //NDX_TmpCSAllianceArtGrp
        if (lCopyToAdminOld)
        {
            if(lDelete)
            {
                NDXTmpCSAllianceArtGrp::deleteRecords(l_copyToOld, only4Alliance);
            }
            NDXTmpCSAllianceArtGrp::updateRecords(copyTo, l_copyToOld, false, l_copyFromSic, only4Alliance);
        }
        else
        {
            if(lDelete)
            {
                NDXTmpCSAllianceArtGrp::deleteRecords(copyTo, only4Alliance);
            }                    
        }
        NDXTmpCSAllianceArtGrp::updateRecords(copyFrom, copyTo, lSic, l_copyFromSic, only4Alliance);

        //NDX_TmpKumUmsCust
        if (lCopyToAdminOld)
        {
            if(lDelete)
            {
                NDXTmpKumUmsCust::deleteRecords(l_copyToOld, only4Alliance);
            }
            NDXTmpKumUmsCust::updateRecords(copyTo, l_copyToOld, false, l_copyFromSic, only4Alliance);
        }
        else
        {
            if(lDelete)
            {
                NDXTmpKumUmsCust::deleteRecords(copyTo, only4Alliance);
            }
        }
        NDXTmpKumUmsCust::updateRecords(copyFrom, copyTo, lSic, l_copyFromSic, only4Alliance);

        //NDX_TmpKumUmsCustArtGrp
        if (lCopyToAdminOld)
        {
            if(lDelete)
            {
                NDXTmpKumUmsCustArtGrp::deleteRecords(l_copyToOld, only4Alliance);
            }
            NDXTmpKumUmsCustArtGrp::updateRecords(copyTo, l_copyToOld, false, l_copyFromSic, only4Alliance);
        }
        else
        {
            if(lDelete)
            {
                NDXTmpKumUmsCustArtGrp::deleteRecords(copyTo, only4Alliance);
            }
        }
        NDXTmpKumUmsCustArtGrp::updateRecords(copyFrom, copyTo, lSic, l_copyFromSic, only4Alliance);
        ttscommit;
    }

    //--> 1.1: NDX/PaffH/30.04.2011
    if (copyFrom == #adminAlliance && copyTo == #admin)
    {
        NDXUmsatzParametersGlobal::setLastCopyAlliance();
    }
    else if (copyFrom == #adminSalesGroup && copyTo == #admin)
    {
        NDXUmsatzParametersGlobal::setLastCopySalesGroup();
        NDXUmsatzParametersGlobal::setLastClose();
    }
    //<-- NDX/PaffH/30.04.2011
    CodeAccessPermission::revertAssert();

    return true;
}
